<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{api}from'../api';const rows=ref<any[]>([]),show=ref(false),form=reactive({username:'',password:'',display_name:'',phone:'',role:'tenant_viewer',active:true});async function load(){rows.value=(await api('/tk-api/enterprise/members')).members;}async function save(){await api('/tk-api/enterprise/members',{method:'POST',body:JSON.stringify(form)});show.value=false;load();}onMounted(load);</script>
<template><section class="panel"><header class="panel-head"><div><span class="eyebrow">TEAM ACCESS</span><h2>企业成员与权限</h2></div><button class="primary" @click="show=!show">新增成员</button></header><form v-if="show" class="inline-form" @submit.prevent="save"><input v-model="form.username" placeholder="登录账号" required><input v-model="form.password" type="password" placeholder="初始密码（至少8位）" required><input v-model="form.display_name" placeholder="姓名"><select v-model="form.role"><option value="tenant_owner">企业主管</option><option value="tenant_operator">企业运维</option><option value="tenant_viewer">只读人员</option></select><button class="primary">保存</button></form><div class="member-grid"><article v-for="x in rows"><span class="avatar">{{(x.display_name||x.username).slice(0,1)}}</span><div><b>{{x.display_name||x.username}}</b><p>{{x.username}}</p></div><span class="role-badge">{{x.role}}</span></article></div></section></template>
